    async fn websocket_client_bounded<F: std::future::Future>(
        cx: &Cx,
        operation: &str,
        future: F,
    ) -> F::Output {
        asupersync::time::timeout(cx.now(), HTTP_OPERATION_BOUND, future)
            .await
            .unwrap_or_else(|_| panic!("{operation} stays within its caller-owned deadline"))
    }

